const test=require('node:test'),assert=require('node:assert/strict'),fs=require('fs'),vm=require('vm');const ctx={console,TextEncoder,TextDecoder,crypto:require('crypto').webcrypto};ctx.globalThis=ctx;ctx.window=ctx;ctx.document=undefined;vm.createContext(ctx);for(const f of ['data.js','clinical-model-v2.js','clinical-addons.js','clinical-library-v3.js','exercise-intelligence-knee.js','exercise-intelligence-next.js','core.js','planner.js','motion-specs.js','motion-specs-intelligence.js'])vm.runInContext(fs.readFileSync('reda-2/'+f,'utf8'),ctx);
test('advanced motion variants have dedicated v2 specs',()=>{for(const key of ['leg-press.bilateral','knee-extension.machine-heavy','spanish-squat.dynamic','split-squat.rfess-loaded','single-leg-squat.box-low','pogo.bilateral','shoulder-er.cable','landmine.single','carry.suitcase','calf-loaded.single','soleus.loaded','hip-thrust.bilateral','step-down.lateral-loaded']){const s=ctx.RedaMotionSpecs.get(key);assert.ok(s,key);assert.equal(s.version,2,key);assert.equal(s.review,'clinical-review-required')}});
test('advanced plans retain exact motion keys',()=>{const p=ctx.RedaPlanner.buildProgram({blueprintId:'knee_pf',stage:'higher',capacity:'high',trainingHistory:'rehab_experienced',goalProfile:'run',equipment:'gym',floorOK:true,band:true});assert.equal(p.intelligenceTier,'performance');assert.ok(p.exercises.every(x=>x.motionKey));assert.ok(p.exercises.some(x=>x.motionKey==='pogo.bilateral'))});
test('no impact enters a strength-only plan',()=>{const p=ctx.RedaPlanner.buildProgram({blueprintId:'knee_pf',stage:'higher',capacity:'high',trainingHistory:'rehab_experienced',goalProfile:'strength',equipment:'gym',floorOK:true,band:true});assert.equal(p.exercises.some(x=>x.motionKey==='pogo.bilateral'),false)});